 function update(e=last){if(!e)return;last=e;const target=document.elementFromPoint(e.clientX,e.clientY),cv=target?.closest?.('#paper .panel-wrap > canvas');if(!cv||e.pointerType==='touch'||!paintTools.includes(getTool())||select.value==='normal'||document.getElementById('viewport').matches('.space-pan,.canvas-panning'))return hide();if(canvas&&canvas!==cv)canvas.style.cursor='';canvas=cv;cv.style.cursor='none';const r=cv.getBoundingClientRect(),circle=getTool()==='airbrush'||getTool()==='erase'||select.value==='size',size=circle?Math.max(1,settings().size*r.width/(+cv.dataset.nativeWidth||1000)):18;Object.assign(cursor.style,{left:e.clientX+'px',top:e.clientY+'px',width:size+'px',height:size+'px'});cursor.dataset.kind=circle?'size':'cross';cursor.classList.toggle('tiny-brush',size<12);cursor.hidden=false;}
